# Calculate Fibonacci numbers up to F_32
def fibonacci(n):
    if n <= 0:
        return 0
    if n == 1:
        return 1
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

F = {}
for i in range(33):
    F[i] = fibonacci(i)

# Print F_2 through F_32
fib_list = [F[i] for i in range(2, 33)]
print("Fibonacci numbers F_2 through F_32:")
print(fib_list)

# Also print F_0 and F_1 for reference
print(f"\nF_0 = {F[0]}, F_1 = {F[1]}")

